S = "Hakeem Force Academy"
QS = [
(S, "Choose the correct word: Ayesha repaired the glasses because her brother ___ them before.", ["had broken", "has broken", "breaks", "would break"], 0, "The repair happened after an earlier action, so the earlier action takes the past perfect tense: had broken.", "Past perfect is formed with had plus the past participle.", [1598]),
(S, "How many divisions does Azad Jammu and Kashmir have?", ["Two", "Three", "Four", "Five"], 1, "AJK is divided into three divisions: Muzaffarabad, Poonch and Mirpur.", "AJK has ten districts in total.", [1830]),
(S, "On which date was Major Aziz Bhatti martyred in the 1965 war?", ["6 September 1965", "10 September 1965", "17 September 1965", "23 September 1965"], 1, "Major Raja Aziz Bhatti was martyred on 10 September 1965 defending the BRB Canal sector near Lahore.", "He was awarded the Nishan-e-Haider.", [2466]),
(S, "Who is known as Baba-e-Sahafat (Father of Journalism) in Pakistan?", ["Maulana Zafar Ali Khan", "Allama Iqbal", "Hasrat Mohani", "Altaf Hussain Hali"], 0, "Maulana Zafar Ali Khan, editor of the daily Zamindar, is most commonly given this title in Pakistani textbooks.", "Sources differ, as some also use this title for other pioneer journalists.", [1337]),
(S, "Who was the son of the Mughal emperor Babur?", ["Akbar", "Humayun", "Jahangir", "Shah Jahan"], 1, "Babur's eldest son and successor was Humayun.", "Humayun's son was Akbar.", [4761]),
(S, "Kala Bagh Dam is proposed on which river, in which district of Punjab?", ["Indus River, Mianwali", "Jhelum River, Mangla", "Chenab River, Sialkot", "Ravi River, Lahore"], 0, "Kalabagh is in Mianwali district where the Indus leaves the salt range. The dam has been proposed there but not built.", "Jinnah Barrage is already built at Kalabagh on the Indus.", [2397]),
(S, "Data Ganj Bakhsh (Hazrat Ali Hujwiri) wrote his famous book Kashf-ul-Mahjoob in which language?", ["Persian", "Arabic", "Urdu", "Punjabi"], 0, "Kashf-ul-Mahjoob, a classic work on Sufism, was written in Persian.", "Data Ganj Bakhsh is buried in Lahore.", [1682, 1705]),
(S, "Ahmad and Naeem have 24 balls together. Naeem has three times as many as Ahmad. How many balls does Ahmad have?", ["4", "6", "8", "12"], 1, "Let Ahmad have x, Naeem 3x. Then 4x = 24, so x = 6.", "Naeem has 18 balls.", [814]),
(S, "A bag has 5 red balls and 3 green balls. What is the probability of drawing a blue ball?", ["0", "1/8", "3/8", "1"], 0, "There is no blue ball in the bag, so favourable outcomes are 0 and the probability is 0/8 = 0.", "An impossible event has probability 0 and a certain event has probability 1.", [2040]),
(S, "In which year did Balochistan become a province of Pakistan after the dissolution of One Unit?", ["1947", "1955", "1970", "1973"], 2, "One Unit was dissolved on 1 July 1970 and Balochistan became a full province.", "Quetta is its capital.", [2296, 3636]),
(S, "Approximately what percentage of Pakistan's area does Balochistan cover?", ["25%", "34%", "44%", "54%"], 2, "Balochistan has about 347,000 square km, which Pakistani textbooks give as roughly 44% of the country.", "Sources differ slightly, as some give about 40 percent depending on the total area used.", [83]),
(S, "Jinnah Barrage is built on which river?", ["Indus", "Jhelum", "Chenab", "Ravi"], 0, "Jinnah Barrage is on the Indus River at Kalabagh in Mianwali district.", "It was earlier called Kalabagh Headworks.", [2490]),
(S, "By what other name is the Ghulam Muhammad Barrage known?", ["Kotri Barrage", "Guddu Barrage", "Sukkur Barrage", "Taunsa Barrage"], 0, "The Ghulam Muhammad Barrage is the Kotri Barrage on the Indus near Hyderabad, Sindh.", "It is the last barrage on the Indus before the sea.", [2902]),
(S, "Who was the President of India when the Indus Waters Treaty was signed in 1960?", ["Rajendra Prasad", "S. Radhakrishnan", "Zakir Husain", "V. V. Giri"], 0, "Rajendra Prasad was India's President from 1950 to 1962, which includes 1960.", "Jawaharlal Nehru was the Prime Minister at that time.", [4747]),
(S, "Which Pakistani batsman has scored the most runs in Test cricket?", ["Younis Khan", "Inzamam-ul-Haq", "Javed Miandad", "Misbah-ul-Haq"], 0, "Younis Khan scored 10,099 Test runs, the highest for Pakistan.", "He is the only Pakistani with over 10,000 Test runs.", [4215, 4225, 1339]),
(S, "Choose the correct word: We are going to the beach ___ car.", ["by", "with", "in the", "on"], 0, "With a means of transport used without an article, the correct preposition is by: by car.", "We say by bus, by train and by air in the same way.", [4363]),
(S, "What is the meaning of the idiom 'beat about the bush'?", ["To avoid coming to the main point", "To search a forest", "To fight bravely", "To speak very loudly"], 0, "The idiom means talking around a subject without addressing it directly.", "The opposite idea is to get straight to the point.", [1126]),
(S, "What is the last letter of the word BEAUTY?", ["T", "U", "Y", "E"], 2, "B-E-A-U-T-Y ends with the letter Y.", "BEAUTY has six letters.", [1121]),
(S, "Which word is a synonym of 'beauty'?", ["Loveliness", "Ugliness", "Hardship", "Anger"], 0, "Loveliness has the same meaning as beauty.", "Ugliness is the antonym of beauty.", [3378]),
]
